                                   .dflt.integer = 0},
        // ignore unknown keys, for cross-version compatibility
        {"", t_ignore},
        {NULL},
        // *INDENT-ON*
    };
    int status;

    memset(&gpsdata->osc, 0, sizeof(gpsdata->osc));
